import { afterEach, describe, expect, it } from 'vitest';
import { DatabaseService } from '../src/database/database.service.js';
import { OperationsRuntimeService } from '../src/operations/operations-runtime.service.js';
import { WorkflowRuntimeService } from '../src/workflows/workflow-runtime.service.js';

afterEach(() => {
  delete process.env.HANDSTACK_DATABASE_ADAPTER;
  delete process.env.HANDSTACK_DATABASE_URL;
});

describe('WorkflowRuntimeService', () => {
  it('keeps definitions and executions tenant-scoped', async () => {
    const runtime = new WorkflowRuntimeService();
    const workflow = await runtime.create({
      organizationId: 'org-1',
      name: 'release',
      trigger: 'manual',
      nodes: [{ id: 'first', kind: 'Condition', config: {} }],
      edges: [],
    });
    expect(await runtime.list('org-2')).toHaveLength(0);
    await expect(runtime.get('org-2', workflow.id)).rejects.toThrow('Workflow not found');
    await runtime.publish('org-1', workflow.id);
    const execution = await runtime.start({
      organizationId: 'org-1',
      workflowId: workflow.id,
      principalId: 'user-1',
      trigger: 'manual',
      payload: { ok: true },
    });
    expect(execution.status).toBe('COMPLETED');
    await expect(runtime.getExecution('org-2', execution.id)).rejects.toThrow(
      'Workflow execution not found',
    );
  });

  it('waits for and resumes after human approval', async () => {
    const runtime = new WorkflowRuntimeService();
    const workflow = await runtime.create({
      organizationId: 'org-1',
      name: 'approval',
      trigger: 'api',
      nodes: [
        { id: 'approval', kind: 'Human Approval', config: { approvers: ['reviewer'] } },
        { id: 'done', kind: 'Condition', config: {} },
      ],
      edges: [{ from: 'approval', to: 'done' }],
    });
    await runtime.publish('org-1', workflow.id);
    const waiting = await runtime.start({
      organizationId: 'org-1',
      workflowId: workflow.id,
      principalId: 'requester',
      trigger: 'api',
      payload: null,
    });
    expect(waiting.status).toBe('WAITING_APPROVAL');
    await expect(runtime.listSteps('org-1', waiting.id)).resolves.toEqual([
      expect.objectContaining({ nodeId: 'approval', status: 'WAITING_APPROVAL' }),
    ]);
    const completed = await runtime.approve({
      organizationId: 'org-1',
      executionId: waiting.id,
      approverId: 'reviewer',
    });
    expect(completed.status).toBe('COMPLETED');
  });

  it('creates and completes an asynchronous Operation for workflow execution', async () => {
    const operations = new OperationsRuntimeService();
    const runtime = new WorkflowRuntimeService(undefined, operations);
    const workflow = await runtime.create({
      organizationId: 'org-async',
      name: 'async workflow',
      trigger: 'api',
      nodes: [{ id: 'first', kind: 'Condition', config: {} }],
      edges: [],
    });
    await runtime.publish('org-async', workflow.id);

    const operation = await runtime.startAsync({
      organizationId: 'org-async',
      workflowId: workflow.id,
      principalId: 'user-async',
      trigger: 'api',
      payload: { async: true },
      idempotencyKey: 'workflow-operation-1',
    });
    expect(operation).toMatchObject({ status: 'PENDING', type: `workflow:${workflow.id}` });

    await new Promise((resolve) => setTimeout(resolve, 0));
    await expect(operations.getOperation('org-async', operation.id)).resolves.toMatchObject({
      status: 'SUCCEEDED',
      result: expect.objectContaining({ executionId: expect.any(String) }),
    });
  });

  it('propagates an already-aborted external signal to the asynchronous Operation', async () => {
    const operations = new OperationsRuntimeService();
    const runtime = new WorkflowRuntimeService(undefined, operations);
    const workflow = await runtime.create({
      organizationId: 'org-cancelled',
      name: 'cancelled workflow',
      trigger: 'api',
      nodes: [{ id: 'first', kind: 'Condition', config: {} }],
      edges: [],
    });
    await runtime.publish('org-cancelled', workflow.id);
    const signal = new AbortController();
    signal.abort();
    const operation = await runtime.startAsync({
      organizationId: 'org-cancelled',
      workflowId: workflow.id,
      principalId: 'user-cancelled',
      trigger: 'api',
      payload: null,
      idempotencyKey: 'workflow-operation-cancelled',
      signal: signal.signal,
    });
    expect(operation).toMatchObject({ status: 'CANCELLED', cancelRequested: true });
    await expect(operations.getOperation('org-cancelled', operation.id)).resolves.toEqual(operation);
  });

  it('hydrates a persisted waiting execution in a new runtime instance', async () => {
    process.env.HANDSTACK_DATABASE_ADAPTER = 'sqlite';
    process.env.HANDSTACK_DATABASE_URL = 'file::memory:';
    const database = new DatabaseService();
    await database.onModuleInit();
    try {
      const first = new WorkflowRuntimeService(database);
      const workflow = await first.create({
        organizationId: 'org-recovery',
        name: 'approval',
        trigger: 'manual',
        nodes: [
          { id: 'approval', kind: 'Human Approval', config: { approvers: ['reviewer'] } },
          { id: 'done', kind: 'Condition', config: {} },
        ],
        edges: [{ from: 'approval', to: 'done' }],
      });
      await first.publish('org-recovery', workflow.id);
      const waiting = await first.start({
        organizationId: 'org-recovery',
        workflowId: workflow.id,
        principalId: 'requester',
        trigger: 'manual',
        payload: 'persisted',
      });

      const restarted = new WorkflowRuntimeService(database);
      await expect(restarted.listSteps('org-other', waiting.id)).rejects.toThrow(
        'Workflow execution not found',
      );
      await expect(restarted.listSteps('org-recovery', waiting.id)).resolves.toEqual([
        expect.objectContaining({ nodeId: 'approval', status: 'WAITING_APPROVAL' }),
      ]);
      await expect(
        restarted.approve({
          organizationId: 'org-other',
          executionId: waiting.id,
          approverId: 'reviewer',
        }),
      ).rejects.toThrow('Workflow execution not found');
      await expect(
        restarted.approve({
          organizationId: 'org-recovery',
          executionId: waiting.id,
          approverId: 'reviewer',
        }),
      ).resolves.toMatchObject({ status: 'COMPLETED', output: 'persisted' });
    } finally {
      await database.onModuleDestroy();
    }
  });
});

import { Inject, Injectable, Optional } from '@nestjs/common';
import { DatabaseService } from '../database/database.service.js';
import { uuidV7 } from '@handstack/domain';
import {
  WorkflowRuntime,
  RepositoryWorkflowStore,
  type WorkflowStore,
  type Workflow,
  type WorkflowEdge,
  type WorkflowExecution,
  type WorkflowNode,
  type WorkflowStepExecution,
  type WorkflowTrigger,
} from '@handstack/workflows';
import { ValidationError } from '@handstack/shared';
import { OperationsRuntimeService } from '../operations/operations-runtime.service.js';

export interface WorkflowDefinitionInput {
  readonly organizationId: string;
  readonly name: string;
  readonly trigger: WorkflowTrigger;
  readonly nodes: readonly WorkflowNode[];
  readonly edges: readonly WorkflowEdge[];
}

@Injectable()
export class WorkflowRuntimeService {
  private readonly workflows = new Map<string, Workflow>();
  private readonly store: WorkflowStore | undefined;
  private readonly runtime: WorkflowRuntime;

  constructor(
    @Optional() @Inject(DatabaseService) database?: DatabaseService,
    @Optional()
    @Inject(OperationsRuntimeService)
    private readonly operations?: OperationsRuntimeService,
  ) {
    this.store =
      database === undefined
        ? undefined
        : new RepositoryWorkflowStore((name) => database.adapter.repository(name));
    this.runtime = new WorkflowRuntime((node, input) => {
      // Core nodes are intentionally side-effect free here. Providers can replace this executor.
      if (node.kind === 'Condition' && typeof node.config.pass === 'boolean' && !node.config.pass)
        return Promise.resolve({ input, skipped: true });
      return Promise.resolve(input);
    }, this.store);
  }

  async list(organizationId: string): Promise<readonly Workflow[]> {
    const durable = (await this.store?.listWorkflows(organizationId)) ?? [];
    for (const workflow of durable) {
      this.workflows.set(this.key(organizationId, workflow.id), workflow);
      this.runtime.register(workflow);
    }
    return [...this.workflows.values()].filter(
      (workflow) => workflow.organizationId === organizationId,
    );
  }

  async get(organizationId: string, workflowId: string): Promise<Workflow> {
    const workflow = this.workflows.get(this.key(organizationId, workflowId));
    if (workflow?.organizationId === organizationId) return workflow;
    const durable = await this.store?.findWorkflow(organizationId, workflowId);
    if (durable === undefined) throw new ValidationError('Workflow not found');
    this.workflows.set(this.key(organizationId, workflowId), durable);
    this.runtime.register(durable);
    return durable;
  }

  async create(input: WorkflowDefinitionInput): Promise<Workflow> {
    const now = new Date();
    const workflow: Workflow = {
      id: uuidV7(),
      tenantId: input.organizationId,
      organizationId: input.organizationId,
      name: input.name,
      trigger: input.trigger,
      nodes: input.nodes,
      edges: input.edges,
      published: false,
      version: 1,
      createdAt: now,
      updatedAt: now,
    };
    this.runtime.register(workflow);
    this.workflows.set(this.key(input.organizationId, workflow.id), workflow);
    await this.store?.saveWorkflow(workflow);
    return workflow;
  }

  async publish(organizationId: string, workflowId: string): Promise<Workflow> {
    const current = await this.get(organizationId, workflowId);
    const published: Workflow = { ...current, published: true, updatedAt: new Date() };
    this.runtime.register(published);
    this.workflows.set(this.key(organizationId, workflowId), published);
    await this.store?.saveWorkflow(published);
    return published;
  }

  start(input: {
    readonly organizationId: string;
    readonly workflowId: string;
    readonly principalId: string;
    readonly trigger: WorkflowTrigger;
    readonly payload: unknown;
    readonly signal?: AbortSignal;
  }): Promise<WorkflowExecution> {
    return this.get(input.organizationId, input.workflowId).then(async () => {
      const execution = await this.runtime.start(input);
      return execution;
    });
  }

  async startAsync(input: {
    readonly organizationId: string;
    readonly workflowId: string;
    readonly principalId: string;
    readonly trigger: WorkflowTrigger;
    readonly payload: unknown;
    readonly idempotencyKey: string;
    readonly signal?: AbortSignal;
  }) {
    if (this.operations === undefined)
      throw new ValidationError('Operations runtime is required for asynchronous workflows');
    const operation = await this.operations.createOperation({
      organizationId: input.organizationId,
      type: `workflow:${input.workflowId}`,
      idempotencyKey: input.idempotencyKey,
    });
    if (operation.status !== 'PENDING') return operation;
    if (input.signal?.aborted) {
      try {
        return await this.operations.operations.update(
          { ...operation, status: 'CANCELLED', cancelRequested: true },
          operation.version,
        );
      } catch {
        return operation;
      }
    }
    let running: typeof operation;
    try {
      running = await this.operations.operations.update(
        { ...operation, status: 'RUNNING' },
        operation.version,
      );
    } catch {
      // A concurrent cancellation may have advanced the operation before work started.
      return operation;
    }
    const controller = new AbortController();
    const onAbort = () => controller.abort();
    if (input.signal?.aborted) controller.abort();
    else input.signal?.addEventListener('abort', onAbort, { once: true });
    const cancellationTimer = setInterval(() => {
      void this.operations?.getOperation(input.organizationId, running.id).then((current) => {
        if (current?.cancelRequested === true || current?.status === 'CANCELLED')
          controller.abort();
      });
    }, 50);
    void this.start({
      organizationId: input.organizationId,
      workflowId: input.workflowId,
      principalId: input.principalId,
      trigger: input.trigger,
      payload: input.payload,
      signal: controller.signal,
    })
      .then(async (execution) => {
        try {
          await this.operations?.operations.update(
            {
              ...running,
              status: controller.signal.aborted
                ? 'CANCELLED'
                : execution.status === 'COMPLETED'
                  ? 'SUCCEEDED'
                  : 'FAILED',
              ...(execution.status === 'COMPLETED'
                ? { result: { executionId: execution.id } }
                : { errorCode: execution.error ?? 'workflow_execution_failed' }),
            },
            running.version,
          );
        } catch {
          // A concurrent API cancellation already advanced the Operation version.
        }
      })
